"""Dimension vocabularies for the channel-neutral turn metric attributes.

Everything in this module is declarative — no runtime state. The enums are
the attribute-value vocabularies for the ``rasa.turn.*`` metrics declared in
:mod:`rasa.tracing.turn.instruments`.
"""

from __future__ import annotations

from enum import Enum


class TurnTriggerType(str, Enum):
    """Trigger that started the turn."""

    SPEECH = "speech"
    TEXT = "text"
    DTMF = "dtmf"
    SILENCE_TIMEOUT = "silence_timeout"


class TurnOutputModality(str, Enum):
    """Modality of the turn's first user-facing output."""

    AUDIO = "audio"
    TEXT = "text"


class TurnOutcome(str, Enum):
    """Terminal outcome of an engine turn.

    Interruptions, such as barge-ins, and cancellations from call teardown or
    shutdown are expected outcomes rather than operation failures.
    """

    COMPLETED = "completed"
    INTERRUPTED = "interrupted"
    CANCELLED = "cancelled"
    ERROR = "error"
